class Inventory {
  constructor(stock) {
    this.stock = new Map();
    for (const [sku, qty] of Object.entries(stock)) {
      this.stock.set(sku, qty);
    }
  }
  reserve(sku, qty) {
    const current = this.stock.get(sku) || 0;
    if (current < qty) throw new InventoryError(`Not enough stock for ${sku}`);
    this.stock.set(sku, current - qty);
  }
  release(sku, qty) {
    const current = this.stock.get(sku) || 0;
    this.stock.set(sku, current + qty);
  }
  available(sku) {
    return this.stock.get(sku) || 0;
  }
}
```
